    [ '2026-10-27', 'Commissions', 'The whole commission flow reviewed and built: private reference photos, the deposit and balance orders, stages and due dates, reminder emails, a shipping email, a Commission files screen, and the customer’s account created at checkout.' ],
    [ '2026-10-27', 'Blog & home page', 'Home page text boxes with a linked menu bar scroll on phones and tablets; clicks go through only from the title bar.' ],
    [ '2026-10-26', 'Blog & home page', 'Home page text boxes can link like the other boxes, boxes follow the Light and Dark looks, the logo color can change, and a tiny gap between titlebar and outline was fixed.' ],
    [ '2026-10-26', 'Behind the scenes', 'Block editor: a one-click “Hide this block” hides a block temporarily, and every text color can be set. Appearance > Design > Styles reflects the theme’s settings.' ],
    [ '2026-10-26', 'Artwork tools', 'A Related Posts editor sets how many matching tags, how many items, grid or stack, the title and the badges; grids show at most three columns on phones. A dark Halloween look and a light holiday look are saved, not active.' ],
    [ '2026-10-24', 'Blog & home page', 'Home page boxes can use random images and a blur for image backgrounds (separate for light and dark), and the spotlight is drawn as an angled beam with CSS gradients.' ],
    [ '2026-10-24', 'Look & design', 'Visitors whose devices use Dark Mode get it automatically; the mobile site menu is a floating window with an outline and transparency you set, and tapping outside closes it.' ],
    [ '2026-10-24', 'Look & design', 'Look > Sharing Icons: turn sharing on and choose among all the services that have an icon; the shortcode reference is a top-level tab of Layout Manager; WooCommerce gray-out overlays work in dark mode.' ],
    [ '2026-10-23', 'Artwork tools', 'A list view with the picture on the left and the details on the right, used in search results, the Art Feed and elsewhere. Detail view uses square thumbnails; diptychs and triptychs show every panel in list view and one image elsewhere; dimensions sit on the info line; miniatures get an “M” mark.' ],
    [ '2026-10-23', 'Artwork tools', 'The view toolbar can be switched on or off sitewide with a default, category, tag and place pages open in detail view, and a visitor’s choice carries over.' ],
    [ '2026-10-23', 'Look & design', 'One placeholder image for the whole site, used wherever a picture is missing; category headers can fold, with the social icons still showing; switching Light and Dark on the Look screen is instant and saving gives feedback.' ],
    [ '2026-10-23', 'Pages & links', 'The About page explains how AI was used to make the site, and logged-in administrators can see product pages while visitors are always sent to the artwork post.' ],
    [ '2026-10-23', 'Blog & home page', 'On the home page the # link of a box lines up with the row it sits in.' ],
    [ '2026-10-22', 'Look & design', 'The menu bar has a search icon you set in Look > Menu Bar with the other icons; all menu bar icons share one round hover.' ],
    [ '2026-10-22', 'Artwork tools', '[artwork sku="234"] shows an artwork wherever you use it, with its own width, alignment and caption options.' ],
    [ '2026-10-22', 'Look & design', 'Top Content banners got styling options (card or plain, a discreet close mark), and can be set per page, post or category.' ],
    [ '2026-10-22', 'Look & design', 'Saved looks simplified: one Factory Default for Light and one for Dark, with link toggles so a change in Dark carries to Light.' ],
    [ '2026-10-22', 'Look & design', 'A site-wide sidebar setting (left or right on wide screens, above or below the content on phones); the Ko-fi button matches the site; desktop sharing buttons for Facebook, Instagram and Bluesky; the quote style has a bar on the left; WooCommerce text and alert colors work in light and dark.' ],
    [ '2026-10-22', 'Pages & links', 'The WordPress menu editor now matches the real menus; the old menus were removed and Main 2026 became Main Menu.' ],
    [ '2026-10-21', 'Look & design', 'Every look setting is edited in one place (Appearance > Look); WooCommerce alerts share one look in light and dark; the About page follows the site.' ],
    [ '2026-10-21', 'Look & design', 'Dark mode, with a light and dark switch in the menu bar, its own backgrounds for the home boxes, an inverted avatar and readable tag cloud, tables and forms.' ],
    [ '2026-10-21', 'Look & design', 'Look settings for the title pills, tagline, home page boxes (black gloss, color gloss, solid color, outline, shadow, fonts), rounded corners for boxes, cards, images and buttons, backgrounds and buttons; saved looks, a live preview and a clearer Save.' ],
    [ '2026-10-21', 'Look & design', 'The logo is built from two parts (monospace and ART) that stack on phones, with separate settings for desktop and mobile.' ],
    [ '2026-10-21', 'Shop & pricing', 'A standalone Price Card shows the artwork or print preview in its own column, with relative print sizes; it replaced the separate Print price card, and Appearance > Price Card can copy its shortcode with your settings.' ],
    [ '2026-10-21', 'Artwork tools', 'The view bar has a Price Card view and a random sort (“Surprise me”). An item that showed as available in the Art Filter although it was sold was fixed.' ],
    [ '2026-10-21', 'Admin toolbar', 'The Market Inventory Manager has a link in the toolbar, and the Older and Newer buttons were fixed.' ],
    [ '2026-10-20', 'Admin toolbar', 'A phone toolbar you set in Settings > Admin toolbar, and one admin screen style across the site.' ],
    [ '2026-10-20', 'Admin toolbar', 'Artwork heads the + New menu, and the toolbar items can be dragged into position for phone and desktop.' ],
    [ '2026-10-20', 'Artwork tools', 'A status panel on the WordPress Dashboard gives an overview of the site.' ],
    [ '2026-10-20', 'Shop & pricing', 'Price cards: a compact version, a style you can set per artwork and per category, price cards can be switched off per category (off for Prints), prices show in bold Courier, and a price may be left blank while a piece is Sold, Private or Gallery.' ],
    [ '2026-10-20', 'Look & design', 'The theme also works with WordPress’s own Appearance editor (menus, fonts, colors, styles), and the Layout Manager’s headers and sidebars screen is easier to scan and edit.' ],
    [ '2026-10-20', 'Pages & links', 'The # links on posts and pages jump past the header to the start of the content.' ],
    [ '2026-10-19', 'Behind the scenes', 'The site is organized as Core, switchable feature plugins and an appearance-only theme. Your own lightbox replaced the old library.' ],
    [ '2026-10-19', 'Artwork tools', 'Quick Artwork Editor: the last digits of the SKU in big bold type, the title is the source of truth for the post title and the caption, frequently used values sit at the top of every dropdown, and price and sales can be changed by a dollar amount.' ],
    [ '2026-10-19', 'Artwork tools', 'The Artwork Editor shows a bigger preview when you roll over a thumbnail, colors the availability states, saves and loads lists, and exchanges lists with the Artwork Sheets generator.' ],
    [ '2026-10-19', 'Prints', 'Show / Hide prints works for framed and unframed separately or together. Print previews open as a lightbox over the blurred page with pinch-zoom and relative print sizes, and a control panel sets the preview background.' ],
    [ '2026-10-19', 'Admin toolbar', 'The black WordPress toolbar has artwork tools: change the price and the availability of the artwork you are looking at.' ],
    [ '2026-10-19', 'Behind the scenes', 'The WordPress Dashboard shortcuts became a plugin of their own, and a smart “unused” folder in the Media Library lists pictures nothing uses, refreshed every night.' ],
    [ '2026-10-19', 'Artwork tools', 'The several ink categories were merged into one.' ],
    [ '2026-10-18', 'Prints', 'Print mockups are drawn on the site; Printful’s are gone.' ],
    [ '2026-10-18', 'Behind the scenes', 'The Media Library got a cleanup and Real Media Library Pro folders.' ],
    [ '2026-10-17', 'Prints', 'Print files are clean copies, not watermarked originals; the artworks that still need a clean photo are flagged.' ],
    [ '2026-10-17', 'Artwork tools', 'Infinite scroll says when you reach the end of the feed and no longer shows a loading note at the bottom.' ],
    [ '2026-10-17', 'Prints', 'Search results say “Prints available”, every print tab has a “See a preview” link above Add to cart, and every printable artwork comes in three unframed sizes.' ],
    [ '2026-10-17', 'Market terminal', 'The Market Inventory Manager lists originals only, never prints, and miniatures are left out of the prints lists.' ],
    [ '2026-10-17', 'Blog & home page', 'The home page has a setting for the picture shown when the site is shared on social media.' ],
    [ '2026-10-16', 'Behind the scenes', 'Every print’s name now carries a clear prefix, and each site got its own robots.txt rules for crawlers.' ],
    [ '2026-10-16', 'Blog & home page', 'Home page editor: the top row (Welcome and News) is editable, boxes can hold formatted text and admin-only notes, every box is listed for Desktop and Phone with an eye icon to show or hide it, and the QR code can show on phones only.' ],
    [ '2026-10-16', 'Look & design', 'Rollover effects in Layout Manager > Appearance & Effects: a subtle grow and lift with a shadow, also for the logo and images; more space between home boxes on phones; the “Return to shop” link can be changed.' ],
    [ '2026-10-16', 'Artwork tools', 'A viewing toolbar on category and archive pages: list or grid, only originals available, items with prints, sort by size, price or date. A switch shows or hides it.' ],
    [ '2026-10-16', 'Prints', 'On the New prints page you set the default prices for prints not yet added, and adding a batch of prints no longer waits for mockups.' ],
    [ '2026-10-16', 'Behind the scenes', 'The # links back to the home page jump faster.' ],
    [ '2026-10-15', 'Prints', 'Prints are made in the background, and a Prints menu shows every print with its status, bulk prices, sizes and frames, and a way to replace a print file.' ],
    [ '2026-10-15', 'Shop & pricing', 'Shipping zones were fixed so every address gets the right rate: North America, then the rest of the world, with prints shipping free everywhere.' ],
    [ '2026-10-15', 'Blog & home page', 'The home page boxes were regrouped one row per menu section with row labels, and a drag-and-drop editor was added in Layout Manager.' ],
    [ '2026-10-15', 'Pages & links', 'New Main Menu and Footer menus went live, with redirects from the retired pages; Available Originals became a real category page; Exhibitions and Upcoming Markets got matching event cards.' ],
    [ '2026-10-15', 'Artwork tools', 'Artworks that had two values in one detail were fixed.' ],
    [ '2026-10-15', 'Shop & pricing', 'Shipping and fine print show only on pieces that are available, and the price card says that originals ship unframed.' ],
    [ '2026-10-15', 'Pages & links', 'The logo links to Available Originals, the “monospace ART” icon left the menu bar, and “My Account” became “Account Settings”. SEO fixes and intro text went into the local landing pages.' ],
    [ '2026-10-14', 'Look & design', 'The elastic, rubber-band scroll went live.' ],
    [ '2026-10-14', 'Behind the scenes', 'Tracking scripts were switched off and the old one-off scripts were retired.' ],
    [ '2026-06-09', 'Commissions', 'The “upload failed” error when uploading a preview image on a commission was investigated.' ],
    [ '2026-06-06', 'Commissions', 'The first real commission went through the system: a deposit order, two previews and a final-payment order.' ],
    [ '2026-05-05', 'Prints', 'A print order shortcode is the first step towards selling prints.' ],
    [ '2026-04-01', 'Shop & pricing', 'Stripe Tax became the sales tax engine (from around April).' ],
    [ '2026-03-28', 'Look & design', 'The header and menu styles were reworked.' ],
    [ '2026-01-16', 'Pages & links', 'A custom 404 page.' ],
    [ '2026-01-15', 'Artwork tools', 'Artwork Sheets can be saved and shared by public link, with their own settings; password-protected pages hide the title on the password form.' ],
    [ '2026-01-12', 'Artwork tools', 'Artwork Sheets begin: a generator that turns chosen artworks into a printable sheet, and clickable feed images with a miniature cover layout.' ],
    [ '2026-01-05', 'Pages & links', 'The Layout Manager is born: default headers and sidebars for the whole site, overrides per category, post, page and product, and sidebar shortcodes.' ],
    [ '2026-01-05', 'Artwork tools', 'The Miniature Set block shows two or three miniatures side by side with one caption; a MailPoet subscription shortcode and styled submit button join the theme; the PayPal Payments plugin is installed.' ],
    [ '2026-01-02', 'Look & design', 'The theme’s styles are written in SASS and its code is reorganized into modules; a shortcode embeds external HTML, search finds an artwork by the last digits of its SKU, and cart and home icons can be placed by shortcode.' ],
    [ '2025-12-31', 'Shop & pricing', 'The Sales Dashboard is created: global and per-category sale controls with schedules, percentage price changes, volume discounts, free shipping rules, a bulk editor and import and export.' ],
    [ '2025-12-25', 'Look & design', 'The theme becomes standalone, no longer built on Astra, and its styles are split into files for global, header, menu, layout, archive, button and WooCommerce.' ],
    [ '2025-12-16', 'Market terminal', 'A market order entry page (the first Inventory Manager) for entering sales at markets, plus an artwork data audit tool and a MailPoet newsletter archive shortcode.' ],
    [ '2025-12-16', 'Shop & pricing', 'When free shipping applies, the other shipping options are hidden.' ],
    [ '2025-12-12', 'Commissions', 'The commission system takes shape: a Commissions tab in My Account where you upload previews for the customer, a final-payment order, and a Product column on the orders list.' ],
    [ '2025-12-03', 'Artwork tools', 'The Art Filter plugin: a search and filter page for the artworks, with custom headers on search and archive pages and size, medium and type labels on thumbnails.' ],
    [ '2025-12-03', 'Look & design', 'The site gets a theme of its own, monospace-art-theme, in place of the Astra child theme.' ],
    [ '2025-12-01', 'Artwork tools', 'The Quick Product plugin appears: a box on a post that links it to a WooCommerce product, the start of “an artwork is a post plus a product”. The first picture becomes the product image automatically, and miniatures get a volume discount.' ],
